import{_ as a,o as e,c as r,ag as i}from"./chunks/framework.DMXcdKmJ.js";const d="/induframe-docs/images/login/workbench-login.png",_=JSON.parse('{"title":"登录与退出","description":"选择正确入口和组织，登录工作台，刷新确认会话并安全退出。","frontmatter":{"title":"登录与退出","description":"选择正确入口和组织，登录工作台，刷新确认会话并安全退出。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/login.md","filePath":"zh/使用指南/登录与退出.md"}'),l={name:"zh/guide/login.md"};function o(n,t,h,s,c,p){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="登录与退出" tabindex="-1">登录与退出 <a class="header-anchor" href="#登录与退出" aria-label="Permalink to &quot;登录与退出&quot;">​</a></h1><p>本页帮助组织成员登录已有平台并结束当前浏览器会话。你需要管理员提供的公共入口、所属组织、账号和密码，且平台已经<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>。</p><p>平台超级管理员使用独立的管理入口；两种账号的区别见<a href="/induframe-docs/zh/concepts/access.html">入口与账号</a>。</p><h2 id="登录工作台" tabindex="-1">登录工作台 <a class="header-anchor" href="#登录工作台" aria-label="Permalink to &quot;登录工作台&quot;">​</a></h2><ol><li>在浏览器打开公共入口，确认页面标题为“登录工作台”。证书不受信任时，先让维护人员核对证书与访问地址。</li><li>有多个组织时，在“选择组织”中搜索或选择所属组织。只有一个组织时自动选中，不显示选择框。</li><li>填写“账号”和“密码”，点击“登录”。只在你管理的设备上按需勾选“记住登录状态”。</li><li>登录后打开左侧“工程管理”。刷新页面，确认仍可查看当前有权限的内容。新安装没有工程时，列表为空是正常的。</li></ol><p><img src="'+d+'" alt="登录工作台页面，包含账号、密码、记住登录状态和登录按钮"></p><p><em>图：公共入口的登录工作台。只有一个可登录组织时不显示选择组织。</em></p><p><strong>成功确认</strong>：进入工作台且能打开有权限的菜单。默认组织管理员使用平台管理员刚重置的密码，可直接进入工作台。</p><h2 id="页面要求设置新密码时" tabindex="-1">页面要求设置新密码时 <a class="header-anchor" href="#页面要求设置新密码时" aria-label="Permalink to &quot;页面要求设置新密码时&quot;">​</a></h2><p>如果出现“设置新的登录密码”，填写“当前密码”“新密码”“确认新密码”，点击“设置密码并进入系统”。新密码应为 8–72 个 UTF-8 字节，与当前密码不同；ASCII 字符每个占一个字节，常见汉字占三个字节。</p><p>成功后自动进入系统；若页面提示“密码已修改，请使用新密码重新登录。”，回到登录页使用新密码。正常首次安装的超级管理员和刚完成首次设置的默认组织管理员不需要额外执行这一步。</p><h2 id="退出当前会话" tabindex="-1">退出当前会话 <a class="header-anchor" href="#退出当前会话" aria-label="Permalink to &quot;退出当前会话&quot;">​</a></h2><ol><li>保存当前编辑内容。</li><li>在侧栏打开账号菜单，点击“登出”。</li><li>在“提示”对话框确认“确定要登出吗？”，点击“确定”。</li><li>确认返回登录页。再次访问工作台地址时，应要求重新登录。</li></ol><p>退出会结束当前浏览器会话。其他设备上的会话按组织登录策略处理，不能把本次退出当作所有设备都已退出。</p><h2 id="登录失败时" tabindex="-1">登录失败时 <a class="header-anchor" href="#登录失败时" aria-label="Permalink to &quot;登录失败时&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面现象</th><th>处理方式</th></tr></thead><tbody><tr><td>租户入口尚未开放</td><td>请平台管理员从内网管理入口完成首次安全设置</td></tr><tr><td>账号或密码错误</td><td>核对入口、组织和账号；不要把平台管理员密码用于组织登录</td></tr><tr><td>提示等待若干秒后重试</td><td>等待提示时长，不连续提交</td></tr><tr><td>出现滑块验证</td><td>完成页面验证后再登录</td></tr><tr><td>登录续期暂不可用或连接超时</td><td>保留未保存编辑，检查访问链路和服务；不能据此认定密码错误</td></tr><tr><td>登录成功但没有所需菜单</td><td>请组织管理员核对账号角色和所属组织</td></tr></tbody></table><p>忘记组织管理员密码时，请平台超级管理员在“组织管理”中重置；忘记普通成员密码时联系组织管理员。平台超级管理员无法登录则联系有服务器管理权限的交付维护人员，保留当前数据。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>刚完成安装时，继续<a href="/induframe-docs/zh/installation/verify.html">确认安装成功</a>。需要交接账号时，向接收者说明<a href="/induframe-docs/zh/concepts/access.html">公共入口与管理入口</a>的区别。</p>',19)])])}const u=a(l,[["render",o]]);export{_ as __pageData,u as default};
